from lxml import etree
import re
from taf.internal.scf.exceptions import ElementNotFound, AttributeSetterNotSupported


class TreeObject(object):
    def __init__(self, tree=None):
        self._tree = tree

    def __repr__(self):
        return etree.tostring(self._tree).decode('utf-8')

    def __str__(self):
        return str(self._tree)

    def remove(self):
        self._tree.getparent().remove(self._tree)

    def __getitem__(self, item):
        return self._tree.attrib[item]

    def __setitem__(self, key, value):
        self._tree.attrib[key] = value

    def __setattr__(self, key, value):
        if key != '_tree':
            raise AttributeSetterNotSupported("To set attributes use, eg. mo['attribute'] = 'abc'")
        else:
            self.__dict__['_tree'] = value


class TreeListObject(TreeObject):
    def __init__(self, tree=None):
        super(TreeListObject, self).__init__(tree)

    def find_single_mo(self, item, tree, ns):
        if tree is not None:
            if ns is not None:
                ns = '{' + ns + '}'
            find_pattern = '''./{ns}managedObject[@distName="{dn}"]'''
            find_string = find_pattern.format(
                ns=ns,
                dn=item
            )
            return tree.find(find_string)

    def find_multiple_mos(self, item, tree, ns):
        if tree is not None:
            xpath_pattern_base = '''managedObject[re:test(@distName, "^{dn}-[0-9]+$")]'''
            xpath_pattern = '''./''' + xpath_pattern_base if ns is None else '''./x:''' + xpath_pattern_base
            xpath_string = xpath_pattern.format(
                ns=ns,
                dn=item
            )
            return tree.xpath(xpath_string, namespaces={'x': ns,
                                                        're': "http://exslt.org/regular-expressions"})

    def find_element(self, item, tree):
        return tree.xpath('''./node()[re:test(@name, "^{item}$")]'''.format(item=item),
                          namespaces={'re': "http://exslt.org/regular-expressions"})[0]

    def append(self, element):
        self._tree.append(element._tree)

    @staticmethod
    def return_scf_element(element, classes):
        for tag, klass in classes:
            if re.match('.*' + tag, element.tag):
                return klass(element)

    def _get_children(self, item, tree, classes):
        if isinstance(item, slice):
            children = tree.getchildren()[item]
            result = []
            for child in children:
                result.append(self.return_scf_element(child, classes))
            return result
        elif isinstance(item, int):
            return self.return_scf_element(tree.getchildren()[item], classes)
        elif isinstance(item, str):
            return super(TreeListObject, self).__getitem__(item)
        raise ElementNotFound("Element {item} not found.".format(item=item))

    def __getslice__(self, i, j):
        return self.__getitem__(slice(i, j))

    def _find_flat_children(self, ns, dist_name=None):
        xpath_string = '''/ns:raml/ns:cmData/ns:managedObject'''
        if dist_name is not None:
            xpath_string += '''[re:test(@distName, "^{dn}/")]'''.format(dn=dist_name)

        return self._tree.xpath(xpath_string, namespaces={'ns': ns,
                                                          're': "http://exslt.org/regular-expressions"})
